package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.person.Grade;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class ImportRatesService {

    /** An imported line, read: the grade, its percent, and its from-date and to-date (none: blank). */
    private record Line(Grade grade, BigDecimal pct, LocalDate from, LocalDate to) {
    }

    private final RateService rates;

    public ImportRatesService(RateService rates) {
        this.rates = rates;
    }

    /** Set a rate per line of grade,rate,from,to, in order, each as the rate form would set it. Every line
     *  is checked first with the rate form's rules; one change: when any line is refused, nothing is set
     *  and nothing is written. Blank lines are skipped; an import with no lines is refused. */
    @Transactional
    public List<Rate> importRates(String sheetId, String user, String text) {
        List<Line> lines = new ArrayList<>();
        int number = 0;
        for (String raw : text.split("\\r?\\n")) {
            number++;
            if (raw.isBlank()) continue;
            lines.add(read(raw, number));
        }
        if (lines.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Import at least one line.");
        }
        List<Rate> set = new ArrayList<>();
        for (Line line : lines) set.add(rates.set(sheetId, user, line.grade(), line.from(), line.to(), line.pct()));
        return set;
    }

    /** A line of grade,rate,from,to; the from-date and to-date may be blank or absent. */
    private static Line read(String raw, int number) {
        String[] fields = raw.split(",", -1);
        if (fields.length < 2 || fields.length > 4) throw refused(number, "it needs a grade, a rate, and at most a from-date and a to-date");
        Grade grade;
        try {
            grade = Grade.valueOf(fields[0].trim());
        } catch (IllegalArgumentException e) {
            throw refused(number, "the grade is not A, B or C");
        }
        BigDecimal pct;
        try {
            pct = new BigDecimal(fields[1].trim());
        } catch (NumberFormatException e) {
            throw refused(number, "the rate is not a number");
        }
        if (pct.signum() < 0 || pct.scale() > 2 || pct.precision() - pct.scale() > 3) {
            throw refused(number, "the rate must be 0.00 or more, with up to three digits and two decimals");
        }
        LocalDate from = date(fields, 2, number, "from-date");
        LocalDate to = date(fields, 3, number, "to-date");
        if (from != null && to != null && to.isBefore(from)) throw refused(number, "the to-date is before the from-date");
        return new Line(grade, pct, from, to);
    }

    private static LocalDate date(String[] fields, int at, int number, String what) {
        if (fields.length <= at || fields[at].isBlank()) return null;
        try {
            return LocalDate.parse(fields[at].trim());
        } catch (DateTimeParseException e) {
            throw refused(number, "the " + what + " is not a date (yyyy-mm-dd)");
        }
    }

    private static ResponseStatusException refused(int number, String why) {
        return new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Line " + number + ": " + why + ".");
    }
}
-- A statement can be taken as of a date on or before the sheet's today: it binds the person's claims
-- as they stood at the end of that date, counting every change made while the sheet's today was on or
-- before it. So each change a figure depends on keeps the sheet's today it was made on (made_on; null:
-- made before this was kept, counting on every date).

-- The statement's date: the date it was taken as of, else the sheet's today when it was taken.
ALTER TABLE statement ADD COLUMN stated_on DATE;
UPDATE statement SET stated_on = taken_on;
ALTER TABLE statement ALTER COLUMN stated_on SET NOT NULL;

-- Each binding of a claim to a figure by a statement, and each loss of one (a later statement leaving it
-- out, its statement cancelled, its moving or splitting), oldest first.
CREATE TABLE claim_binding (
    claim_id   BIGINT  NOT NULL REFERENCES claim (id),
    position   INT     NOT NULL,
    on_date    DATE,
    stated     BOOLEAN NOT NULL,
    stated_due DECIMAL(12, 2),
    PRIMARY KEY (claim_id, position)
);
INSERT INTO claim_binding (claim_id, position, stated, stated_due)
    SELECT id, 0, TRUE, stated_due FROM claim WHERE stated;

-- Each setting of a rate, oldest first: a rate set for a grade and from-date replaces the one before it.
CREATE TABLE rate_change (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100)  NOT NULL REFERENCES sheet (id),
    grade     VARCHAR(1)    NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    from_date DATE,
    to_date   DATE,
    pct       DECIMAL(5, 2) NOT NULL,
    made_on   DATE
);
CREATE INDEX rate_change_sheet ON rate_change (sheet_id, id);
INSERT INTO rate_change (sheet_id, grade, from_date, to_date, pct)
    SELECT sheet_id, grade, from_date, to_date, pct FROM rate ORDER BY id;

-- Each recording of a dated setting, oldest first: a value recorded for a key and from-date replaces
-- the one before it.
CREATE TABLE setting_change (
    id            BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id      VARCHAR(100) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(100) NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(200) NOT NULL,
    made_on       DATE
);
CREATE INDEX setting_change_sheet ON setting_change (sheet_id, id);
INSERT INTO setting_change (sheet_id, setting_key, from_date, setting_value)
    SELECT sheet_id, setting_key, from_date, setting_value FROM sheet_setting_dated;

-- When a person was added, given each grade, put on each hold and retired.
ALTER TABLE person ADD COLUMN added_on DATE;
ALTER TABLE person ADD COLUMN retired_made_on DATE;
ALTER TABLE person_grade ADD COLUMN made_on DATE;
ALTER TABLE person_hold ADD COLUMN made_on DATE;

